    override func keyDown(with event: NSEvent) {
        if handleEditorKey(event) { return }
        super.keyDown(with: event)
    }

    /// Bare keys only, and never while text is being edited — a modifier-less
    /// letter must not be stolen from the timecode field or (later) an inline
    /// text clip. Everything with a modifier arrives as a menu key
    /// equivalent instead, which is also where it gets validated.
    ///
    /// Internal rather than private since road map 2's phase 8b: the preview
    /// window is a second window, so its content view is not in this
    /// controller's responder chain and has nowhere to send a bare Space or
    /// J/K/L. It hands the event here rather than carrying a second copy of the
    /// map (`PreviewWindowController.swift`), which is the one thing that could
    /// make the two windows' transports disagree.
    func handleEditorKey(_ event: NSEvent) -> Bool {
        if view.window?.firstResponder is NSText { return false }
        // And never while a sheet is attached — the same invariant
        // `validateUserInterfaceItem` opens with below, because this map is
        // not only transport: `t` adds a text clip, `w`/`e` trim, `m` marks,
        // `,`/`.` nudge, `i`/`o` write the range. A sheet captures a project
        // handle and reads it again later, so the document must not move
        // under it. Until phase 8b that held here for free and needed no line,
        // since a sheet takes the editor window's key status and this method
        // was simply unreachable while one was up. But a sheet is WINDOW-modal
        // rather than application-modal (measured: with one attached
        // `NSApp.modalWindow` is nil, and the preview panel is visible and
        // `canBecomeKey`), and the panel forwards its bare keys straight here,
        // where no validator stands — `t` added a text clip behind an open
        // export card that had already captured the project it was about to
        // write, and Remove Silences, which computes its spans ONCE, would
        // have rippled ranges that no longer described the timeline. The guard
        // belongs beside the key map rather than in the panel: both windows
        // inherit it, no second copy can drift, and the editor's own path pays
        // nothing for a case it cannot reach.
        if view.window?.attachedSheet != nil { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first else {
            return false
        }
        guard EditorKey.isBare(flags, scalar: scalar.value) else { return false }
        let shift = flags.contains(.shift)
        switch scalar.value {
        case UInt32(NSLeftArrowFunctionKey):
            stepFrames(shift ? -10 : -1)
        case UInt32(NSRightArrowFunctionKey):
            stepFrames(shift ? 10 : 1)
        case UInt32(NSUpArrowFunctionKey):
            previousEditPoint(nil)
        case UInt32(NSDownArrowFunctionKey):
            nextEditPoint(nil)
        case UInt32(NSHomeFunctionKey):
            goToStart(nil)
        case UInt32(NSEndFunctionKey):
            goToEnd(nil)
        case 27: return deselectActionCommand()
        default:
            return handleEditorCharacter(Character(scalar), shift: shift)
        }
        return true
    }

    /// Compared as a lowercased STRING, not a `Character`: lowercasing is not
    /// one-to-one in every locale (a Turkish "İ" becomes two scalars), and
    /// `Character(String)` traps on anything but exactly one.
    private func handleEditorCharacter(_ character: Character, shift: Bool) -> Bool {
        switch character.lowercased() {
        case " ":
            playPause(nil)
        case "j":
            shuttle(forward: false)
        case "k":
            playback.pause()
        case "l":
            shuttle(forward: true)
        case "i":
            setInPoint(nil)
        case "o":
            setOutPoint(nil)
        case "n":
            toggleSnapping(nil)
        case "m":
            addMarker(nil)
        case "w":
            trimStartToPlayhead(nil)
        case "e":
            trimEndToPlayhead(nil)
        case "t":
            addTextClip(nil)
        case "c":
/// And nothing is taken while a sheet is attached. An auto-repeat of a Space
/// the window took is swallowed. A non-editable field editor (a selectable
/// label), a slider, the window itself and every custom inspector control
/// are the transport's.
///
/// `handleEditorCharacter`'s `case " "` in `EditorViewController` stays for
/// the preview panel's forward (`PreviewWindowController.keyDown`) and is
/// dead for this window.
enum SpaceKeyRoute: Equatable { case transport, held, responder }

enum SpaceKey {
    /// nil unless `event` is a key-DOWN of keyCode 49 whose device-independent
    /// flags ⊆ [.shift, .capsLock]. Pure: reads only its arguments.
    static func route(
        _ event: NSEvent, firstResponder: NSResponder?, sheetAttached: Bool
    ) -> SpaceKeyRoute? {
        guard event.type == .keyDown, event.keyCode == 49 else { return nil }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard flags.subtracting([.shift, .capsLock]).isEmpty else { return nil }
        if sheetAttached { return .responder }
        if (firstResponder as? NSTextView)?.isEditable == true { return .responder }
        if firstResponder is NSButton || firstResponder is NSSegmentedControl
            || firstResponder is CanvasOverlayView
        {
            return .responder
        }
        if event.isARepeat { return .held }
        return .transport
    }
}

/// When the editor window takes the keys back from text (spec §11 K-4):
/// typing is focus-averse. Only a click, or a command that exists to type,
/// gives text the keys; a click outside it, Tab (unless Full Keyboard Access
/// is on), and Return in a one-line field hand them back to the content
/// view — the root that holds the bare-key map — BEFORE dispatch, so Space
/// plays the moment typing ends.
///
/// Before dispatch because of what dispatch did: a click on the timeline,
/// which refuses first responder, left the field editor attached, and
/// AppKit's own Return re-selected the field after its commit — both behind
/// no focus ring, so the next Space was typed into a field that looked left.
/// Each field still commits through its own end-of-editing path, as on any
/// blur. Pure, so a probe can ask it.
enum TextFocus {
    /// The text taking keys when `responder` is editable text — every field
    /// editor, the Text tab's area, the canvas's inline editor, the
    /// composer — else nil.
    static func typing(_ responder: NSResponder?) -> NSTextView? {
        guard let text = responder as? NSTextView, text.isEditable else { return nil }
        return text
    }

    /// Where a click keeps the typing: a field editor's field, or the
    /// `OptionFieldControl` that frames it (its margins and chevron are the
    /// field's own); else the text view's scroll view, so a scroller is
    /// inside; else the text view.
    static func host(of text: NSTextView) -> NSView {
        if text.isFieldEditor, let field = text.delegate as? NSView {
            return (field.superview as? OptionFieldControl) ?? field
        }
        return text.enclosingScrollView ?? text
    }

    /// True when the key-down `event` leaves `text`: Tab or ⇧Tab in any
    /// text, unless `fullKeyboardAccess` — then Tab is AppKit's key-view
    /// loop, how such a user reaches a control (K-1's exception); Return or
    /// keypad Enter in a field editor (⇧ ⇪, and the keypad and fn flags,
    /// allowed). ⌃Tab, ⌥Return and ⌘ are AppKit's; a multi-line view routes
    /// its own Return (`TextEditKey`). Never while an input method has
    /// marked text.
    static func leavesOnKey(
        _ event: NSEvent, in text: NSTextView, fullKeyboardAccess: Bool
    ) -> Bool {
        guard event.type == .keyDown, !text.hasMarkedText() else { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        switch event.keyCode {
        case 48:
            return !fullKeyboardAccess && flags.subtracting([.shift, .capsLock]).isEmpty
        case 36, 76:
            return text.isFieldEditor
                && flags.subtracting([.shift, .capsLock, .numericPad, .function]).isEmpty
        default:
            return false
        }
    }

    /// True when a mouse-down whose content hit is `hit` leaves `text`: a
    /// hit outside its host. nil — the click is outside the content view,
    /// on the title bar — never leaves.
    static func leavesOnClick(hit: NSView?, in text: NSTextView) -> Bool {
        guard let hit else { return false }
        return !hit.isDescendant(of: host(of: text))
    }
}

/// The bare-key map's modifier rule, read by `handleEditorKey` (#61).
enum EditorKey {
    /// Device-independent part of `flags` minus [.shift, .capsLock] must be empty, except that on a
    /// function-key scalar (0xF700...0xF8FF) .numericPad and .function are also allowed. ⌘ ⌥ ⌃ .help never. Pure.
    static func isBare(_ flags: NSEvent.ModifierFlags, scalar: UInt32) -> Bool {
    /// responder now the content view. A field that refuses to resign keeps
    /// the event, and nothing is taken while a sheet is attached.
    private func leaveText(for event: NSEvent) -> Bool {
        guard attachedSheet == nil, let text = TextFocus.typing(firstResponder),
              let content = contentView
        else { return false }
        let leaves: Bool
        switch event.type {
        case .keyDown:
            leaves = TextFocus.leavesOnKey(
                event, in: text, fullKeyboardAccess: NSApp.isFullKeyboardAccessEnabled)
        case .leftMouseDown, .rightMouseDown, .otherMouseDown:
            let point = content.superview?.convert(event.locationInWindow, from: nil)
                ?? event.locationInWindow
            leaves = TextFocus.leavesOnClick(hit: content.hitTest(point), in: text)
        default:
            leaves = false
        }
        return leaves && makeFirstResponder(content)
    }
}
import AppKit

/// The inspector's foot (spec §11 CI-10): "Refused: " and the rule's own
/// sentence, VERBATIM, when the core refused a person's edit.
/// `ProjectDocument.applyEdit` has already beeped; this is the one thing a
/// person sees that an identity does not show them.
///
/// It lasts until the PROJECT changes — `clearIfStale` runs at the top of
/// every inspector refresh and clears it once `editedProject` is another
/// handle, which is an applied edit, an undo, a redo or a scope change — or
/// until it is clicked. A playhead or selection move keeps the same handle,
/// so it keeps the strip. Hidden, it is detached from the foot's stack, so
/// it takes no room.
final class InspectorRefusalStrip: NSView {
    private(set) var text: String?
    /// The handle the refusal was shown under. Weak: a handle nothing else
    /// holds is one the project has moved away from, and nil is not it.
    private weak var project: ReelProject?
    private let label = NSTextField(wrappingLabelWithString: "")
    /// Its width pinned to the foot's, made on a show: hidden, the strip is
    /// detached from the foot's stack, and a constraint made once in
    /// `loadView` need not survive that.
    private var spanning: NSLayoutConstraint?

    init() {
        super.init(frame: .zero)
        wantsLayer = true
        isHidden = true
        label.font = DS.sans(11)
        label.textColor = DS.textStrong
        label.isSelectable = false
        label.maximumNumberOfLines = 3
        label.cell?.truncatesLastVisibleLine = true
        label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        label.translatesAutoresizingMaskIntoConstraints = false
        addSubview(label)
        NSLayoutConstraint.activate([
            label.topAnchor.constraint(equalTo: topAnchor, constant: 8),
            label.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -8),
            label.leadingAnchor.constraint(
                equalTo: leadingAnchor, constant: InspectorMetrics.inset),
            label.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRefusalStrip does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// A wrapping label needs its width to know its height.
    override func layout() {
        super.layout()
        let width = max(bounds.width - 2 * InspectorMetrics.inset, 0)
        guard label.preferredMaxLayoutWidth != width else { return }
        label.preferredMaxLayoutWidth = width
        super.layout()
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.hoverFill.setFill()
        bounds.fill()
        DS.border.setFill()
        NSRect(x: 0, y: 0, width: bounds.width, height: 1).fill()
    }

    func show(_ refusal: ReelRefusal, under project: ReelProject?) {
        let sentence = "Refused: " + refusal.reason
        text = sentence
        self.project = project
        label.stringValue = sentence
        toolTip = sentence
        isHidden = false
        needsDisplay = true
    }

    /// Clears once the project is not the handle the refusal was shown under.
    func clearIfStale(_ project: ReelProject?) {
        guard text != nil, project !== self.project else { return }
        clear()
    }

    func clear() {
        guard text != nil else { return }
        text = nil
        project = nil
        label.stringValue = ""
        toolTip = nil
        isHidden = true
    }

    override func mouseDown(with event: NSEvent) {
        clear()
    }

    /// Pins the strip to `container`'s width unless that pin is still active.
    func span(_ container: NSView) {
        guard spanning?.isActive != true, isDescendant(of: container) else { return }
        spanning = widthAnchor.constraint(equalTo: container.widthAnchor)
        spanning?.isActive = true
    }
}

extension InspectorViewController {
    /// The editor's forward of `projectDocumentDidRefuse`.
    func showRefusal(_ refusal: ReelRefusal) {
        guard isViewLoaded else { return }

    // MARK: - Metrics (spec §3's table)

    static let toolbarHeight = DS.toolbarHeight
    /// The redesign's inspector width (`DS.panelWidth`, 304). The two clamps
    /// below are the window's, not the design's, and stay where they were.
    static let defaultInspectorWidth = DS.panelWidth
    static let minInspectorWidth: CGFloat = 280
    static let maxInspectorWidth: CGFloat = 440
    /// 300, not the 240 that predates the redesign: lane heights are per KIND
    /// now (`DS.trackHeights`), so a Medium text/video/audio stack is
    /// 44 + 84 + 60 pt of lanes plus 2 pt between each, the 22 pt ruler, the
    /// timeline's own 36 pt bar and 4 pt of lane inset top and bottom — 260 pt
    /// before a fourth track, against a 240 pt pane that clipped the last one.
    /// The DEFAULT only: the two clamps below and the persisted
    /// `timelineHeightKey` are untouched, so a pane the user has already sized
    /// keeps the size they gave it.
    static let defaultTimelineHeight: CGFloat = 300
    static let minTimelineHeight: CGFloat = 140
    /// The timeline may not eat more than 60 % of the window (spec §3).
    static let maxTimelineFraction: CGFloat = 0.6
    static let minCanvasWidth: CGFloat = 380
    static let minUpperHeight: CGFloat = 220
    /// The void margin around the preview (spec §4.2).
    static let canvasMargin: CGFloat = 24

    // MARK: - Persisted view state
import AppKit

/// The editor's two split views, which know when a person is dragging a
/// divider (#327).
///
/// AppKit's divider drag runs inside `mouseDown(with:)` until the mouse is
/// up, so the flag is true for exactly the resizes a drag causes. The
/// notification's `NSSplitViewDividerIndex` user info is not that test:
/// NSSplitView.h says that since macOS 12 it is posted "during resize and
/// layout events as well", so a window resize carries it too.
final class PaneSplitView: NSSplitView {
    private(set) var isDraggingDivider = false

    override func mouseDown(with event: NSEvent) {
        isDraggingDivider = true
        defer { isDraggingDivider = false }
        super.mouseDown(with: event)
    }
}

extension EditorViewController {
    /// A drag of `main`'s divider saves `timeline`'s height under
    /// `timelineHeightKey`; of `upper`'s, `inspector`'s width under
    /// `inspectorWidthKey` (not while hidden, not ≤ 1 pt). Any other resize —
    /// `notification.object` not dragging, as a window resize, a restore or
    /// ⌥⌘I is — saves nothing, so the remembered size is the one a person
    /// chose and a new window opens with it.
    static func savePaneSize(
        after notification: Notification, main: PaneSplitView, upper: PaneSplitView,
        timeline: NSView, inspector: NSView, to defaults: UserDefaults
    ) {
        guard let split = notification.object as? PaneSplitView, split.isDraggingDivider
        else { return }
        if split === main, timeline.bounds.height > 1 {
            defaults.set(Double(timeline.bounds.height), forKey: timelineHeightKey)
        } else if split === upper, !inspector.isHidden, inspector.bounds.width > 1 {
            defaults.set(Double(inspector.bounds.width), forKey: inspectorWidthKey)
        }
    }
}
import AppKit

/// The document window. Nothing but sizing and the subtitle lives here — the
/// editor itself is `EditorViewController`.
final class EditorWindowController: NSWindowController {
    init(document: ProjectDocument) {
        let window = EditorWindow(
            contentRect: NSRect(x: 0, y: 0, width: 1280, height: 800),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false)
        window.contentViewController = EditorViewController(document: document)
        window.backgroundColor = DS.chromeBackground
        window.titlebarAppearsTransparent = false
        window.minSize = NSSize(width: 900, height: 620)

        // Content size: the canvas at a comfortable preview scale plus the
        // chrome around it (toolbar 44, inspector 304, timeline 300), clamped
        // to 85 % of the screen. A 4K project must not open a 4K window.
        let canvas = document.project.snapshot.canvas
        var contentSize = NSSize(
            width: min(canvas.size.width, 1280) + EditorViewController.defaultInspectorWidth,
            height: min(canvas.size.height, 720) + EditorViewController.toolbarHeight
                + EditorViewController.defaultTimelineHeight)
        if let screen = NSScreen.main {
            let limit = screen.visibleFrame
            contentSize.width = min(contentSize.width, limit.width * 0.85)
            contentSize.height = min(contentSize.height, limit.height * 0.85)
        }
        contentSize.width = max(contentSize.width, 900)
        contentSize.height = max(contentSize.height, 620)
        window.setContentSize(contentSize)
        window.center()

        super.init(window: window)

        // The title tracks the document name through NSDocument's own
        // synchronizeWindowTitleWithDocumentName; only the subtitle is ours,
        // and the editor refreshes it whenever the canvas changes.
        window.subtitle = EditorWindowController.subtitle(for: document)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("EditorWindowController does not support NSCoder")
    }

    /// "1920 × 1080 · 30 fps · edited" — the document facts that are never in
    /// the title. The chrome cleanup made the title bar carry the project's
    /// identity (there is no status bar and the toolbar no longer shows
    /// document meta), so the dirty flag has to read out here in words: under
    /// `ProjectDocument.autosavesInPlace` AppKit never sets
    /// `NSWindow.isDocumentEdited`, so there is no close-button dot and this
    /// suffix is the only dirty indicator the window has. Static so
    /// `EditorViewController` can refresh it after a `set_canvas` without
    /// reaching into this controller's internals.
    ///
    /// **Both halves are published, and not from here.** The only caller that
    /// re-reads this is `EditorViewController.refreshFromDocument`, which runs
    /// off `.projectDocumentDidChange`; `ProjectDocument.publishingEditedState`
